import React, { useState, useMemo, useEffect } from 'react';
import './Table.scss';
import Pagination from "../pagination/Pagination";
import StatusBadge from "../statusBadge/StatusBadge";
import IconButton from "../iconButton/IconButton";
import MenuBlock  from '../menuBlock/MenuBlock';
import { MpaIcon } from "../icon/MpaIcon";
import Header from "./Header";
import { NormalTextLink } from '../normalTextLink';
 import Switch from '../switch/Switch';
import { SwitchProps } from "../switch";
import Dropdown from '../dropdown/Dropdown';
import { DropdownProps } from "../dropdown";
import Input from "../textField/TextField";
import { TextFieldProps } from "../textField";
import { getStatusColour,getIcon, getDefaultTooltipText  } from "../utils/commonUtils";

type SortDirection = "asc" | "desc" | null;
export interface MoreActionItem{
  menuItems: {
    label: string;
  }[];
}

export interface DataItem {
  type: "text" | "country" | "currency" | "number" | "boolean" | "select" | "status" | "action" | "typeStatus" | "multiLineText"; 
  displayName: string;
  value?: string | boolean | number;
  align?: "left" | "right" | "center"; 
  displayName2?: string; //for mu ltiLineText
}

export interface ActionItem {
  icon?: string;
  title?: string;
  href?: string;
  tooltipText?: string;
  tooltipPlacement?: "top" | "bottom" | "left" | "right" | undefined;
  isDisabled?: boolean;
  showDivider?: boolean;
}

export interface TableProps {
  /**
   * Unique identifier for the accordion component
   */
  id:string;
  /**
   * Determines the headers for the main table.
   */
  headers: { 
    sequence: string; 
    displayName: string; 
    tooltipText?: string; 
    align?: "left" | "right" | "center"; 
    width?: string;
    isEditable?: boolean;
    isEditorType? : "text" | "date" | "dropdown" | "switch";
    dropdownOptions?: { label: string; value: string }[];
    isSortable?: boolean;
    sortDirection?: SortDirection;
  }[];

   /**
   * Determines the Sub headers for the sub table.
   */
  subHeaders: { 
    sequence: string; 
    displayName: string; 
    tooltipText?: string; 
    align?: "left" | "right" | "center"; 
    width?: string;
    isEditable?: boolean;
    isEditorType? : "text" | "date" | "dropdown" | "switch";
    dropdownOptions?: { label: string; value: string }[];
  }[];

  /**
   * records to render in table
  */
  records: {
    id: string;
    mainData: DataItem[];  
    subData: {
      parentId: string;
      subId: string;
      data: DataItem[];
    }[];
    mainActionData: ActionItem[],
    subActionData: ActionItem[]
  }[]

   /**
    * Enable first row data to be clickable
   */
   isFirstItemClickable?: boolean; 
   /**
    * Visual variant for actions
    */
   variant?: "icon" | "label" | "label-and-icon";
 
   /**
    * Pagination behavior
    */
   paginationType?: "table" | "responsive" | "slider" ;
 
   /**
    * Shape of interactive elements
    */
   shape?: "circle" | "square";
 
   /**
    * colour theme
    */
   colour?: "primary" | "secondary" | "tertiary";
 
   /**
    * border outline style
    */
   outline?: "outline" | "none";
   // onItemsPerPageChange: (items: number) => void;  
 
   /** 
    * action handler
    */
   onActionClick?: (action: string, rowid: string, rowData: DataItem[] ) => void;
 
  /** 
    * Sub action handler
    */
   onSubActionClick?: (action: string, parentId: string, rowid: string, rowData: any[] ) => void;
   
   /**
    * Determine show/ hide the pagination
    */
   showPagination: boolean;
 
 /** 
    * Text field Props
    */  
   TextFieldProps?: Partial<TextFieldProps>;
 
   /** 
    * action on Text change
    */  
   onTextChange?: (rowId: string,headerSequence: string, value:string) => void;
 
   /** 
    * Switch Props
    */  
   SwitchProps?: Partial<SwitchProps>;
 
   /** 
    * action on switch change
    */  
   OnSwitchChange?: (rowId: string, headerSequence: string, value:boolean) => void;
 
   /** 
    * action on switch change
    */  
   OnDropdownChange?: (rowId: string,headerSequence: string, value:string) => void;
   /** 
    * Dropdown Props
    */  
   DropdownProps?: Partial<DropdownProps>;
 
   /** 
    * Pagination total pages
    */ 
   totalPageNumber: number;
 
   /** 
    * Pagination total Records
    */ 
   totalRecords?: number;

   /** 
    * Pagination page change
    */ 
   handlePaginationPageChange?: (page: number ) => void;
 
   /** 
    * Pagination dropdown page change
    */ 
   handlePaginationRowPerPageChange?: (page: number ) => void;

 /** 
   * action on sorting change
  */ 
  onSortAction?: (sequence: string, direction: Exclude<SortDirection, null>) => void;
}

export const ExpandableTable: React.FC<TableProps> = ({ 
  id,
  headers, 
  subHeaders,
  records, 
  isFirstItemClickable,
  variant="icon", 
  paginationType="table",
  shape, 
  colour="primary",
  outline,
  onActionClick,
  onSubActionClick,
  SwitchProps,
  OnSwitchChange,
  showPagination=true,
  DropdownProps,
  OnDropdownChange,
  totalPageNumber = 0,
  handlePaginationPageChange,
  handlePaginationRowPerPageChange,
  TextFieldProps,
  onTextChange,
  onSortAction,
  totalRecords
}) => {

  const [expandedRows, setExpandedRows] = useState<Set<number>>(new Set());
  const [itemsPerPage, setItemsPerPage] = useState(10); 
  const [currentPage, setCurrentPage] = useState(1);  
  const [showMoreMainAction, setShowMoreMainAction] =  useState<number | null>(null);
  const [showMoreSubAction, setShowMoreSubAction] = useState<{
    parentId: string;
    subIndex: string;
  } | null>(null);  
  const [updatedRows, setUpdatedRows] = useState(records);
  const [updatedSubRows, setUpdatedSubRows] = useState(records);  
  
  const startIndex = (currentPage - 1) * itemsPerPage;
  //const currentRows = records.slice(startIndex, startIndex + itemsPerPage);
  const currentRows = showPagination
                      ? records.slice(startIndex, startIndex + itemsPerPage) // internal pagination
                      : records; // parent-controlled pagination
  const [updatedHeaders, setUpdatedHeaders] = useState(headers);

  const handleItemsPerPageChange = (event:number) => {
    const newItemsPerPage = Number(event);
    setItemsPerPage(newItemsPerPage);
    setCurrentPage(1);
    handlePaginationRowPerPageChange?.(newItemsPerPage);
  };

  const handlePageChange = (page: number) => {
     setCurrentPage(page);
     handlePaginationPageChange?.(page);
  };

  const toggleSubTable = (index: number) => {
    setExpandedRows((prev) => {
      const newExpandedRows = new Set(prev);
      if (newExpandedRows.has(index)) {
        newExpandedRows.delete(index);
      } else {
        newExpandedRows.add(index);
      }
      return newExpandedRows;
    });
  };

  const handleSubActions = (parentId: string, subIndex: string) => {
    const isSame = showMoreSubAction?.parentId === parentId && showMoreSubAction?.subIndex === subIndex;
    setShowMoreSubAction(isSame ? null : { parentId, subIndex });
    setShowMoreMainAction(null);
  };

  const handleMainActions = (rowIndex: number) => {
    setShowMoreMainAction(prevIndex => prevIndex == rowIndex ? null : rowIndex);
    setShowMoreSubAction(null);
  };

  const updateMainAction = (action: string, rowid: string, rowIndex: number) => {
    setShowMoreMainAction(null);
    if (onActionClick) {
      onActionClick(action, rowid, updatedRows[rowIndex].mainData);
    }
  }
  
  const updateSubAction = (action: string, parentId: string, rowid: string, rowIndex: number) => {
    setShowMoreSubAction(null);
    if (onSubActionClick) {
      onSubActionClick(action, parentId, rowid, updatedSubRows[rowIndex].subData.find(sub => sub.subId === rowid)?.data || []);
    }
  }

  let tableClassName = [
    "mpa-table",
  ].filter(Boolean).join(" ");

  useEffect(() => {
    setUpdatedRows(records);
    setUpdatedSubRows(records);    
  }, [records]);

  useEffect(() => {
      setUpdatedHeaders(headers); 
  }, [headers]);

  const handleTextChange = (rowId: string, itemIndex: number, header: string, value: string) => {
    setUpdatedRows((prev) => {
      const newRows = [...prev];
      const rowIndex = newRows.findIndex((row) => row.id === rowId);
      if (rowIndex > -1) {
        const row = { ...newRows[rowIndex] };
        const newMainData = [...row.mainData];
        newMainData[itemIndex] = { ...newMainData[itemIndex], value: value };
        row.mainData = newMainData;
        newRows[rowIndex] = row;
      }
      return newRows;
    });

    onTextChange?.(rowId,header, value);
  };

  const handleDropdownChange = (rowId: string, itemIndex: number, header: string, value: string) => {
    setUpdatedRows((prev) => {
      const newRows = [...prev];
      const rowIndex = newRows.findIndex((row) => row.id === rowId);
      if (rowIndex > -1) {
        const row = { ...newRows[rowIndex] };
        const newMainData = [...row.mainData];
        newMainData[itemIndex] = { ...newMainData[itemIndex], value: value };
        row.mainData = newMainData;
        newRows[rowIndex] = row;
      }
      return newRows;
    });

    OnDropdownChange?.(rowId,header, value);
  };

  const handleSwitchChange = (rowId: string, itemIndex: number, header: string, checked: boolean) => {
    setUpdatedRows((prev) => {
      const newRows = [...prev];
      const rowIndex = newRows.findIndex((row) => row.id === rowId);
      if (rowIndex > -1) {
        const row = { ...newRows[rowIndex] };
        const newMainData = [...row.mainData];
        newMainData[itemIndex] = { ...newMainData[itemIndex], value: checked };
        row.mainData = newMainData;
        newRows[rowIndex] = row;
      }
      return newRows;
    });

    OnSwitchChange?.(rowId, header, checked);
  };

  const handleActionClick = (action: string, rowid: string, rowIndex: number) => {
    if (onActionClick) {
      onActionClick(action, rowid, updatedRows[rowIndex].mainData);      
    }
  };

  const handleSubActionClick = (action: string, parentId: string, rowid: string, rowIndex: number) => {
    if (onSubActionClick) {
      onSubActionClick(action, parentId, rowid, updatedSubRows[rowIndex].subData.find(sub => sub.subId === rowid)?.data || []);      
    }
  };

  const handleSortAction = (sequence: string, direction: "asc" | "desc") => {
    const newHeaders = updatedHeaders.map(h =>
      h.sequence === sequence ? { ...h, sortDirection: direction } : { ...h, sortDirection: null }
    );
    setUpdatedHeaders(newHeaders);
    onSortAction?.(sequence, direction); // still inform parent
  };

  const renderSubTable = (subTableData: any[], subTableHeaders: any[], subActionData: any[], dataIndex: number ) => {
    if (!subTableData || !subTableHeaders) return null;
    return (
      <>
      {/* Sub Table Header */}
      <tr className="sub-header-row">
        <td></td>       
        <Header headers={subHeaders}/>   
      </tr>
      
      {/* Sub Table Data */}
      {subTableData.map((subRow, subIndex) => {
        const matchingActionRow = subActionData[subIndex];        
        return (
          <tr key={`sub-${dataIndex}-${subIndex}`} className="sub-row">
            <td></td> 
            {subRow.data.map((subItem: DataItem, subItemIndex: number) => {
              const SubActionHref = matchingActionRow?.data?.[0]?.href;
              return(
              <td key={subItemIndex} style={{ textAlign: subItem.align }}>
                {subHeaders[subItemIndex]?.isEditable
                  ? (
                  <>
                  {subHeaders[subItemIndex]?.isEditorType == 'text' && (
                  <Input
                    id={`text-${subRow.id}-${subItemIndex}`}
                    type="text"
                    value={updatedSubRows[dataIndex]?.mainData[subIndex]?.displayName || ""}                    
                    onChange={(e) => handleTextChange(subRow.id,subIndex,subHeaders[subIndex]?.sequence, e.target.value)}
                    {...TextFieldProps}
                  />
                  )}

                  {subHeaders[subItemIndex]?.isEditorType == 'date' && (
                  <Input
                    id={`date-${subRow.id}-${subItemIndex}`}
                    type="date"
                    value={updatedSubRows[dataIndex]?.mainData[subItemIndex]?.displayName || ""}
                    onChange={(e) => handleTextChange(subRow.id,subItemIndex,subHeaders[subItemIndex]?.sequence, e.target.value)}
                    {...TextFieldProps}
                  />
                  )}

                  {subHeaders[subItemIndex]?.isEditorType == 'dropdown' && (                                   
                  <Dropdown
                    id={`dropdown-${subRow.id}-${subItemIndex}`}
                    options={subHeaders[subItemIndex]?.dropdownOptions || []}
                    selectedValue={updatedSubRows[dataIndex]?.mainData[subItemIndex]?.value?.toString() || ""}
                    onChange={(value) => handleDropdownChange(subRow.id,subItemIndex,subHeaders[subItemIndex]?.sequence, value)}
                    {...DropdownProps}  
                  />
                  )}        

                  {subHeaders[subItemIndex]?.isEditorType == 'switch' && (                      
                    <Switch
                    id={`switch-${subRow.id}-${subItemIndex}`}
                    checked={Boolean(updatedSubRows[dataIndex]?.mainData[subItemIndex]?.value)}
                    value={updatedSubRows[dataIndex]?.mainData[subItemIndex]?.value?.toString() || "false"}                                 
                    onChange={(e) => handleSwitchChange(subRow.id, subItemIndex, subHeaders[subItemIndex]?.sequence , e.target.checked)}
                    {...SwitchProps}                  
                    />
                    )}
                  </>  
                ) : (
                  subItem.type === "status" ? (    
                  <StatusBadge 
                      id={"statusBadgeId"} 
                      label={subItem.displayName} 
                      colour={getStatusColour(subItem.value?.toString())}
                    />
                    ) : subItem.type === "typeStatus" ? (
                  <StatusBadge 
                  id="statusBadgeId"
                  label={subItem.displayName}
                    colour={
                    subItem.value === "success"
                      ? "success"
                      : subItem.value === "error"
                      ? "error"
                      : subItem.value === "warning"
                      ? "warning"
                      : "primary"
                    }
                  leadingIcon={
                  subItem.value === "success"
                    ? "CircleCheck_Filled"
                    : subItem.value === "error"
                    ? "AlertTriangle_Filled"
                    : subItem.value === "warning"
                    ? "AlertTriangle_Filled"
                    : "InfoCircle_Filled"
                  }
                />
                  ): subItem.type === "multiLineText" ? ( 
                  <>
                  <span className="multi-line-text-2">{subItem.displayName2}</span>
                  <br/>   
                  <span className="multi-line-text">{subItem.displayName}</span>
                  </>                        
                  ): (
                  subItemIndex === 0 && isFirstItemClickable ? (
                    <NormalTextLink 
                      id="normalTextLinkId" 
                      target='_blank' 
                      href={SubActionHref}
                    > {subItem.displayName}
                    </NormalTextLink>
                  ):(
                    subItem.displayName
                  )                        
                  )                    
                )}     
              </td>
            )
              })}
            <td>
              <div className="table-action">
                <div className="action-btn">            
                    {matchingActionRow?.data.slice(0, 3).map((subActionItem: ActionItem, i: any) => {                           
                      const iconComponent = getIcon(subActionItem.icon ?? "");
                      const subActionTooltipText = getDefaultTooltipText(subActionItem.title ?? "");
                      if (!iconComponent) return null;
                      return (
                        <IconButton
                          key={i}
                          id="iconButtonId"
                          icon={iconComponent}
                          disabled={subActionItem.isDisabled}
                          size="large"
                          colour="onSurface"
                          btnType="standard"                  
                          tooltipText= {subActionItem.tooltipText ? subActionItem.tooltipText : subActionTooltipText}
                          tooltipPlacement={subActionItem.tooltipPlacement ? subActionItem.tooltipPlacement : "top"}
                          onClick={() =>
                            handleSubActionClick(
                              subActionItem.title ?? "",
                              subRow.parentId,
                              subRow.subId,                                                                                    
                              dataIndex
                            )
                          }
                        />
                      );
                    })}

                   {matchingActionRow?.data.length > 3 && (
                      <IconButton
                        id="iconButtonId"
                        icon="DotsVertical"
                        size="large"
                        colour="onSurface"
                        btnType="standard"
                        tooltipText= "More"
                        tooltipPlacement="top"
                        onClick={() => handleSubActions(subRow.parentId, subIndex.toString())}
                      />
                    )} 

                  {showMoreSubAction?.parentId === subRow.parentId &&
                    showMoreSubAction?.subIndex === subIndex.toString() && (
                      <div className="action-block">
                        <MenuBlock
                          id="menuBlockId"
                          menuItems={matchingActionRow.data.slice(3).map((item:any) => ({
                            label: item.title,
                          }))}                          
                            onItemClick={(item) => updateSubAction(
                                  item.label,
                                  subRow.parentId,
                                  subRow.subId,                                                                                    
                                  dataIndex
                            )}
                        />
                      </div>
                  )}
                </div>
              </div>
            </td>
          </tr>
        );
      })}
      </>
    );
  };

  return (
    <div id={id} className={tableClassName}>
      <table className="main-table">
        <thead>
          <tr> 
            <th></th>      
            <Header headers={updatedHeaders} onSortAction={handleSortAction}/>
          </tr>
        </thead>
        <tbody>
        {Array.isArray(currentRows) && currentRows.map((data, dataIndex) => (         
          <React.Fragment key={dataIndex}>
            <tr className={expandedRows.has(dataIndex) ? `${colour} selected` : ''}>
              {currentRows.some(r => r.subData?.length) && (
                <td onClick={() => toggleSubTable(dataIndex)}>
                  {data.subData?.length > 0 && (
                    <span className={`icon-rotate ${expandedRows.has(dataIndex) ? 'icon-rotate-up' : ''}`}>
                      <MpaIcon iconName="ChevronDown" />
                    </span>
                  )}
                </td>
              )}

              {data.mainData.map((item, itemIndex) => {
                const firstActionHref = data.mainActionData?.[0]?.href;
                return (
                  <td key={itemIndex} style={{ textAlign: item.align }}>  
                      {headers[itemIndex]?.isEditable
                      ? (
                      <>
                      {headers[itemIndex]?.isEditorType == 'text' && (
                        <Input
                            id={`text-${data.id}-${itemIndex}`}
                            type="text"
                            value={updatedRows[dataIndex]?.mainData[itemIndex]?.displayName || ""}
                           
                            onChange={(e) => handleTextChange(data.id,itemIndex,headers[itemIndex]?.sequence, e.target.value)}
                            {...TextFieldProps}
                        />
                      )}

                      {headers[itemIndex]?.isEditorType == 'date' && (
                        <Input
                            id={`date-${data.id}-${itemIndex}`}
                            type="date"
                            value={updatedRows[dataIndex]?.mainData[itemIndex]?.displayName || ""}
                            onChange={(e) => handleTextChange(data.id,itemIndex,headers[itemIndex]?.sequence, e.target.value)}
                            {...TextFieldProps}
                        />
                      )}

                      {headers[itemIndex]?.isEditorType == 'dropdown' && (                                   
                        <Dropdown
                          id={`dropdown-${data.id}-${itemIndex}`}
                          options={headers[itemIndex]?.dropdownOptions || []}
                          selectedValue={updatedRows[dataIndex]?.mainData[itemIndex]?.value?.toString() || ""}
                          onChange={(value) => handleDropdownChange(data.id,itemIndex,headers[itemIndex]?.sequence, value)}
                          {...DropdownProps}  
                        />
                      )}        

                      {headers[itemIndex]?.isEditorType == 'switch' && (                      
                      <Switch
                        id={`switch-${data.id}-${itemIndex}`}
                        checked={Boolean(updatedRows[dataIndex]?.mainData[itemIndex]?.value)}
                        value={updatedRows[dataIndex]?.mainData[itemIndex]?.value?.toString() || "false"} 
                                                
                        onChange={(e) => handleSwitchChange(data.id, itemIndex, headers[itemIndex]?.sequence , e.target.checked)}
                        {...SwitchProps}                  
                      />
                      )}
                      </>  
                    ) : (
                      item.type === "status" ? (    
                        <StatusBadge 
                              id={"statusBadgeId"} 
                              label={item.displayName} 
                              colour={getStatusColour(item.value?.toString())}
                            />
                          ) : item.type === "typeStatus" ? (
                        <StatusBadge 
                        id="statusBadgeId"
                        label={item.displayName}
                          colour={
                            item.value === "success"
                              ? "success"
                              : item.value === "error"
                              ? "error"
                              : item.value === "warning"
                              ? "warning"
                              : "primary"
                          }
                      leadingIcon={
                        item.value === "success"
                          ? "CircleCheck_Filled"
                          : item.value === "error"
                          ? "AlertTriangle_Filled"
                          : item.value === "warning"
                          ? "AlertTriangle_Filled"
                          : "InfoCircle_Filled"
                      }
                    />
                      ): item.type === "multiLineText" ? ( 
                        <>
                        <span className="multi-line-text-2">{item.displayName2}</span>
                        <br/>   
                        <span className="multi-line-text">{item.displayName}</span>
                        </>                        
                        ): (
                        itemIndex === 0 && isFirstItemClickable ? (
                            <NormalTextLink 
                                id="normalTextLinkId" 
                                target='_blank' 
                                href={firstActionHref}
                            > {item.displayName}
                            </NormalTextLink>
                        ):(
                            item.displayName
                        )                        
                      )                    
                    )}                    
                </td>
                )
                
              })}

              <td>  
                <div className='table-action'> 
                  <div className='action-btn'>                        
                  <>
                    {data.mainActionData.slice(0, 3).map((item, itemIndex) => {
                        const iconComponent = getIcon(item.icon ?? "");
                        const tooltipText = getDefaultTooltipText(item.title ?? "");
                        return (
                            <React.Fragment key={itemIndex}>             
                                <IconButton
                                  id="iconButtonId"                              
                                  icon={iconComponent!}
                                  disabled={item.isDisabled}
                                  size="large"
                                  colour="onSurface"
                                  btnType="standard"
                                  tooltipText= {item.tooltipText ? item.tooltipText : tooltipText}
                                  tooltipPlacement={item.tooltipPlacement ? item.tooltipPlacement : "top"}
                                  onClick={() =>
                                      handleActionClick(
                                        item.title ?? "",
                                        data.id,                                                                                    
                                        dataIndex
                                      )
                                    }
                                />            
                            </React.Fragment>
                          );                          
                      })}

                      {data.mainActionData?.length > 3  && (
                        <IconButton
                          id="iconButtonId"
                          icon="DotsVertical"
                          size="large"
                          colour="onSurface"
                          btnType="standard"
                          tooltipText= "More"
                          tooltipPlacement="top"
                          onClick={() => handleMainActions(dataIndex)}
                        />
                      )}

                      {showMoreMainAction === dataIndex && (
                        <div className='action-block'>                      
                          <MenuBlock
                            id="menuBlockId"
                            menuItems={data.mainActionData
                              .slice(3)
                              .filter((item) => typeof item.title === "string")
                              .map((item) => ({
                                leadingIcon: item.icon,
                                label: item.title as string,
                                showDivider: item.showDivider, 
                              }))}                            
                               onItemClick={(item) => updateMainAction(
                                  item.label,
                                  data.id,                                                                                    
                                  dataIndex
                            )}
                          /> 
                        </div>                 
                      )} 
                    </>
                  </div>                  
                </div>
              </td>
               
            </tr>            
             {expandedRows.has(dataIndex) && data.subData?.length > 0 && (                
                renderSubTable(data.subData, subHeaders, data.subActionData, dataIndex )
            )}
          </React.Fragment>
        ))}

        </tbody>
      </table>
      
      {showPagination && (
        <Pagination
           id={`paginationId-${id}`}
          totalPages={totalPageNumber}
          totalRecords={totalRecords}
          onPageChange={handlePageChange}
          onItemsPerPageChange={handleItemsPerPageChange}          
          variant={variant}
          colour={colour}
          shape={shape}
          outline={outline}
          type={paginationType}
        />
      )}
      
    </div>
  );
};

export default ExpandableTable;
